{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "name": "Surveillance Data",
    "operation": "add",
    "widgets_json": {
      "evidence_files": {
        "name": "Evidence Files",
        "description": "Browse case evidence documents.",
        "endpoint": "/evidence-files",
        "type": "multi_file_viewer",
        "w": 20,
        "h": 14,
        "staleTime": 900000,
        "params": [
          {
            "paramName": "file",
            "type": "endpoint",
            "label": "File",
            "optionsEndpoint": "/evidence-file-options",
            "multiSelect": true,
            "default": [],
            "roles": ["fileSelector"]
          }
        ]
      },
      "alert_metric": {
        "name": "Open Alerts",
        "description": "Open alert count.",
        "endpoint": "/alert-count",
        "type": "metric",
        "w": 5,
        "h": 4,
        "staleTime": 900000
      },
      "case_notes": {
        "name": "Case Notes",
        "description": "Notes for one surveillance case.",
        "endpoint": "/case-notes",
        "type": "markdown",
        "w": 12,
        "h": 8,
        "staleTime": 900000,
        "params": [
          {
            "paramName": "case_id",
            "type": "text",
            "label": "Case",
            "default": "C-1042",
            "description": "Case identifier."
          }
        ]
      }
    },
    "apps_json": [
      {
        "name": "Evidence Live",
        "description": "Evidence files, alerts, and notes.",
        "tabs": {
          "evidence": {
            "id": "evidence",
            "name": "Evidence",
            "layout": [
              {
                "i": "evidence_files",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 12
              }
            ]
          },
          "signals": {
            "id": "signals",
            "name": "Signals",
            "layout": [
              {
                "i": "alert_metric",
                "x": 0,
                "y": 0,
                "w": 8,
                "h": 5
              }
            ]
          }
        }
      }
    ]
  }
}

